globalThis.KENGURU_LEGACY = [[2009,"3–4 классы",[[834,229,"Сколько треугольников на рисунке?",{},"D","Треугольники на рисунке",[["Рассмотри голову","Два уха и мордочка — это три треугольника."],["Рассмотри остальные части","Ещё два треугольника — маленькая лапка у туловища и длинный хвост. Шея, туловище и две нижние детали имеют по четыре стороны. Всего 5 треугольников."]],""],[834,108,"",{},"C","Умножение и сложение",[["Начни с произведения","200 × 9 = 1 800."],["Прибавь остальные числа","1 800 + 200 = 2 000, а 2 000 + 9 = 2 009."]],""],[834,72,"Сколько всего вершин у четырех кубиков?",{"0":[47.2,40.5,31.3,24.1],"1":[198.4,40.5,31.1,24.1],"2":[351.6,40.5,31.3,24.1],"3":[505,40.5,28.4,24.1],"4":[651.5,40.5,31.6,24.1]},"A","Вершины кубиков",[["Посчитай вершины одного кубика","У кубика по четыре вершины на верхней и нижней гранях, всего восемь."],["Умножь на число кубиков","Каждый из четырёх кубиков даёт восемь вершин. Всего 4 × 8 = 32."]],""],[834,208,"",{"0":[47.2,40.5,31.3,24.1],"1":[47.2,74.6,31.1,24.1],"2":[47.2,108.7,31.3,24.1],"3":[47.2,142.8,28.4,24.1],"4":[47.2,176.8,31.6,24.1]},"B","Где находится кенгуру",[["Проверь круг и квадрат","Кенгуру нарисован внутри контура круга и внутри контура квадрата."],["Проверь треугольник","Кенгуру лежит ниже нижней стороны треугольника и потому за его пределами. Подходит ответ Б."]],""],[834,99,"В пятиэтажном доме в каждом подъезде на каждом этаже расположено по 4 квартиры. На каком этаже находится квартира с номером 71?",{"0":[47.2,67.6,31.3,24.1],"1":[198.4,67.6,31.1,24.1],"2":[351.6,67.6,31.3,24.1],"3":[505,67.6,28.4,24.1],"4":[651.4,67.6,31.6,24.1]},"C","Квартира номер 71",[["Найди подъезд","В каждом подъезде 5 × 4 = 20 квартир. После трёх подъездов проходят номера от 1 до 60. Квартира 71 — в четвёртом подъезде."],["Распредели номера по этажам","На первом этаже квартиры 61–64, на втором — 65–68, на третьем — 69–72. Квартира 71 находится на третьем этаже."]],""],[834,182,"На клетчатой бумаге нарисовано число 930 (см. рисунок). Сколько маленьких квадратиков должно поменять цвет, чтобы получилось число 806?",{"0":[47.2,103.9,31.3,24.1],"1":[198.4,103.9,31.1,24.1],"2":[351.6,103.9,31.3,24.1],"3":[47.2,138,28.4,24.1],"4":[198.4,138,31.6,24.1]},"B","Из 930 в 806",[["Сравни цифры попарно","Для 9 → 8 надо закрасить одну клетку слева под серединой. Для 3 → 0 надо закрасить две недостающие клетки слева и убрать среднюю клетку в центральном ряду. Это три изменения."],["Посчитай последнее изменение","Для 0 → 6 нужно убрать клетку справа над серединой и закрасить центральную клетку. Итого 1 + 3 + 2 = 6 изменений."]],""],[834,104,"Вася подсчитал число дней в двух идущих подряд месяцах. Какое число он не мог получить?",{"0":[47.2,72.4,31.3,24.1],"1":[198.4,72.4,31.1,24.1],"2":[351.6,72.4,31.3,24.1],"3":[505,72.4,28.4,24.1],"4":[651.5,72.4,31.6,24.1]},"C","Дни в соседних месяцах",[["Найди самый короткий месяц","Самый короткий месяц — февраль, в нём 28 или 29 дней. С обеих сторон от него месяцы по 31 дню. Даже с коротким февралём получается не меньше 28 + 31 = 59 дней."],["Проверь остальные пары","Два других соседних месяца дают по меньшей мере 60 дней. 58 дней получить нельзя."]],""],[862,180,"Шоколадная плитка состоит из одинаковых долек. Маленький Владик разделил ее «по-честному»: сначала он отломал полоску из 5 долек для бабушки, а затем полоску из 7 долек для дедушки (см. рисунок). Сколько долек у него осталось?",{"0":[53.7,148.6,31.3,24.1],"1":[204.9,148.6,31.1,24.1],"2":[358.1,148.6,31.3,24.1],"3":[511.5,148.6,28.4,24.1],"4":[658,148.6,31.6,24.1]},"B","Две полоски шоколада",[["Найди размеры плитки","Первая полоска идёт сверху вниз на всю высоту и содержит 5 долек. После неё в нижней горизонтальной полоске остаётся 7 долек, значит, оставшаяся часть плитки имеет ширину 7 долек."],["Вычти нижний ряд","После второй полоски остаются 5 − 1 = 4 ряда по 7 долек. Всего 4 × 7 = 28 долек."]],""],[862,72,"Произведение цифр двузначного числа не может равняться",{"0":[53.7,40.5,31.3,24.1],"1":[204.9,40.5,31.1,24.1],"2":[358.1,40.5,31.3,24.1],"3":[511.5,40.5,28.4,24.1],"4":[658,40.5,31.6,24.1]},"D","Произведение двух цифр",[["Проверь возможные произведения","40 = 5 × 8, 36 = 4 × 9, 20 = 4 × 5, а 12 = 3 × 4. Все множители в этих равенствах могут быть цифрами."],["Рассмотри число 13","У 13 есть только множители 1 и 13. Число 13 само не цифра, поэтому такое произведение невозможно."]],""],[862,187,"В 3 часа ночи в замке появилось Привидение. Часы на башне замка, которые до этого показывали правильное время, пошли с обычной скоростью, но в другую сторону. Привидение исчезло с рассветом, в 4 часа 45 минут. Какое время в этот момент показывали часы?",{"0":[53.7,121.6,31.3,24.1],"1":[318.2,121.6,31.1,24.1],"2":[584.7,121.6,31.3,24.1],"3":[53.7,155.6,28.4,24.1],"4":[318.2,155.6,31.6,24.1]},"B","Часы пошли назад",[["Найди прошедшее время","Между 3:00 и 4:45 прошло 1 час 45 минут."],["Отсчитай столько же назад","От 3:00 отсчитай час назад до 2:00 и ещё 45 минут до 1:15. Часы показывали 1 час 15 минут."]],""],[862,153,"В танцевальной студии занимались 25 мальчиков и 19 девочек. Каждую неделю в группу приходят два новых мальчика и три новых девочки. Через сколько недель мальчиков и девочек в этой студии станет поровну?",{"0":[53.7,121.7,31.3,24.1],"1":[204.9,121.7,31.1,24.1],"2":[358.1,121.7,31.3,24.1],"3":[511.5,121.7,28.4,24.1],"4":[658,121.7,31.6,24.1]},"A","Мальчики и девочки в студии",[["Посчитай начальную разницу","Вначале мальчиков больше на 25 − 19 = 6 человек."],["Учти приход новых ребят","За неделю приходят 2 мальчика и 3 девочки. Девочки каждую неделю сокращают разницу на одного человека. Через 6 недель мальчиков и девочек станет поровну."]],""],[862,72,"У скольких трехзначных чисел сумма цифр равна 2?",{"0":[53.7,40.6,31.3,24.1],"1":[204.9,40.6,31.1,24.1],"2":[358.1,40.6,31.3,24.1],"3":[511.5,40.6,28.4,24.1],"4":[658,40.6,31.6,24.1]},"D","Трёхзначные числа",[["Выбери цифру сотен","Первая цифра может быть только 1 или 2. Если взять 2, двум другим цифрам остаётся сумма 0. Получается 200."],["Проверь случай с единицей","Если первая цифра 1, две другие дают сумму 1. Это 1 и 0 в любом порядке. Получаются 110 и 101. Всего 3 числа."]],""],[862,194,"На картинке справа изменили цвет каждой клеточки: белый – на красный, и наоборот. Что получилось?",{"0":[79.8,163.1,31.3,24.1],"1":[218,163.1,31.1,24.1],"2":[358.1,163.1,31.3,24.1],"3":[504.4,163.1,28.4,24.1],"4":[644.7,163.1,31.6,24.1]},"D","Белые и красные клетки",[["Перекрась верхнюю половину","В новом первом ряду будут закрашены клетки 1, 2 и 4, во втором — 3 и 4. Считай слева направо."],["Перекрась нижнюю половину","В третьем ряду будут закрашены клетки 1 и 4, а в четвёртом — 1, 2 и 3. Все четыре ряда совпадают с рисунком Г."]],""],[862,167,"В комнате сидят несколько кошек и собак. Кошачьих лап в комнате вдвое больше, чем собачьих носов. Тогда кошек в комнате",{"0":[53.7,67.6,31.3,24.1],"1":[451.4,67.6,31.1,24.1],"2":[53.7,101.7,31.3,24.1],"3":[451.4,101.7,28.4,24.1],"4":[53.7,135.8,31.6,24.1]},"C","Кошачьи лапы и собачьи носы",[["Свяжи лапы с носами","У одной кошки четыре лапы. Если кошачьих лап вдвое больше, чем собачьих носов, на каждые четыре лапы приходится два носа."],["Вернись к животным","У каждой собаки один нос, значит, на одну кошку приходится две собаки. Кошек вдвое меньше."]],""],[840,270,"Город разделен улицами на квадратные кварталы. Машина выезжает из точки М и на каждом перекрестке поворачивает налево или направо. Проехав один квартал, машина повернула направо, потом три раза налево, а потом еще два раза направо. На каком из рисунков изображен маршрут машины?",{"0":[53.7,154,31.3,24.1],"1":[215.6,154,31.1,24.1],"2":[377.7,154,31.3,24.1],"3":[511.5,154,28.4,24.1],"4":[671,154,31.6,24.1]},"E","Маршрут машины",[["Прочитай повороты по порядку","Если первый квартал машина едет вверх от М, дальше поворот направо ведёт вправо. Три левых поворота затем ведут вверх, влево и вниз. Машина объезжает квадрат и возвращается на первый перекрёсток."],["Дорисуй последние два отрезка","Теперь машина смотрит вниз. Два правых поворота ведут сначала влево, затем вверх. Квадрат справа и эти два отрезка слева есть на рисунке Д."]],""],[840,153,"Белки Алли, Элли и Салли нашли вместе семь орехов. Каждая из них нашла хотя бы по одному ореху, и у всех оказалось разное число орехов. Алли нашла орехов меньше всех, а Элли – больше всех. Сколько орехов нашла Элли?",{"0":[53.7,121.7,31.3,24.1],"1":[165,121.7,31.1,24.1],"2":[278.2,121.7,31.3,24.1],"3":[391.5,121.7,28.4,24.1],"4":[491.4,121.7,31.6,24.1]},"A","Орехи трёх белок",[["Начни с трёх разных чисел","Три наименьших разных положительных числа — 1, 2 и 3. В сумме это 6 орехов."],["Добавь седьмой орех","Если добавить его к 1 или 2, две белки получат одинаковое число орехов. Добавь к 3. Тогда белки нашли 1, 2 и 4 ореха, а у Элли больше всех — 4."]],""],[840,153,"Аня и Петя живут на набережной. Слева от дома Ани на набережной находится 47 домов, а справа – 23 дома. От дома Пети слева и справа по набережной находится одинаковое число домов. Сколько домов расположено между домами Ани и Пети?",{"0":[53.7,121.6,31.3,24.1],"1":[204.9,121.6,31.1,24.1],"2":[358.1,121.6,31.3,24.1],"3":[511.5,121.6,28.4,24.1],"4":[658,121.6,31.6,24.1]},"B","Дома на набережной",[["Найди номера домов в ряду","Всего домов 47 + 1 + 23 = 71. Дом Ани 48-й слева. Петин дом посередине ряда, поэтому перед ним 35 домов, а он сам 36-й."],["Посчитай дома между ними","Разница номеров 48 − 36 = 12. Между домами 12 − 1 = 11 домов."]],""],[840,187,"Из палочек можно выкладывать цифры как на рисунке. Какова сумма цифр самого большого числа, которое удастся выложить, использовав ровно 15 палочек?",{"0":[53.7,121.6,31.3,24.1],"1":[204.9,121.6,31.1,24.1],"2":[358.1,121.6,31.3,24.1],"3":[53.7,155.6,28.4,24.1],"4":[205,155.6,31.6,24.1]},"D","Самое большое число из палочек",[["Найди максимум цифр","На любую изображённую цифру уходит не меньше 3 палочек. Из 15 палочек получается не больше 5 цифр. Пятизначное число больше любого числа с меньшим числом цифр."],["Выбери самые большие цифры","Для пяти цифр каждая должна состоять ровно из трёх палочек. Так выложены 1 и 7. Самое большое число — 77 777, сумма его цифр равна 5 × 7 = 35."]],""],[840,153,"Букет состоит из 4 цветков: красного, голубого, желтого и белого. Пчела Майя садится на каждый цветок в букете только один раз. Она начинает с красного цветка и не перелетает с желтого сразу на белый. Сколькими способами Майя может облететь все цветы?",{"0":[53.7,121.6,31.3,24.1],"1":[204.9,121.6,31.1,24.1],"2":[358.1,121.6,31.3,24.1],"3":[511.5,121.6,28.4,24.1],"4":[658,121.6,31.6,24.1]},"B","Маршруты пчелы Майи",[["Посчитай все порядки после красного","Три оставшихся цветка можно посетить 3 × 2 × 1 = 6 способами."],["Убери два запрещённых порядка","Если жёлтый должен сразу вести на белый, эту пару можно поставить перед голубым или после него. Такие два порядка запрещены. Значит, допустимых маршрутов 6 − 2 = 4."]],""],[840,192,"Будем называть шестизначное число счастливым, если у него сумма цифр, стоящих на нечетных местах, равна сумме цифр, стоящих на четных местах. В каком случае можно заполнить пустые места цифрами так, чтобы получилось счастливое число?",{"0":[53.7,121.7,31.3,24.1],"1":[304.9,121.7,31.1,24.1],"2":[558,121.7,31.3,24.1],"3":[53.7,160.4,28.4,24.1],"4":[304.9,160.4,31.6,24.1]},"D","Счастливое шестизначное число",[["Сравни границы сумм","Каждый пропуск можно заполнить цифрой от 0 до 9. В А нечётная сумма не меньше 14, чётная не больше 11. В Б эти границы 21 и 20. В В нечётная сумма равна 12, чётная не больше 11. В Д нечётная сумма равна 4, чётная не меньше 8."],["Заполни цифры в Г","В Г сумма на чётных местах равна 2 + 9 + 8 = 19. На нечётных уже есть 1. Чтобы получить 19, в оба пропуска надо поставить по 9. Получается 129 998."]],""],[862,210,"Какую фигуру нельзя составить из двух костяшек домино, изображенных справа?",{"0":[79.9,179.3,31.3,24.1],"1":[205,179.3,31.1,24.1],"2":[325,179.3,31.3,24.1],"3":[438.2,179.3,28.4,24.1],"4":[558,179.3,31.6,24.1]},"E","Костяшки домино",[["Проверь направления точек","У исходных костяшек диагонали из двух и трёх точек идут из верхнего левого угла в нижний правый. Поворот на пол-оборота сохраняет эту диагональ. Если положить костяшку горизонтально, диагональ пойдёт в другую сторону."],["Разбей квадраты на костяшки","Квадраты А и Б собираются из двух вертикальных костяшек, а В и Г — из двух горизонтальных. В Д диагонали у костяшек разные, значит, одна должна лежать вертикально, а другая горизонтально. Так квадрат из двух костяшек не собрать."]],""],[862,153,"Дикарь Пятница написал в строчку несколько различных чисел, не превосходящих 10. Робинзон Крузо заметил, что в любой паре соседних чисел одно из них делится на другое без остатка. Какое наибольшее количество чисел мог выписать Пятница?",{"0":[53.7,121.7,31.3,24.1],"1":[204.9,121.7,31.1,24.1],"2":[358.1,121.7,31.3,24.1],"3":[511.5,121.7,28.4,24.1],"4":[658,121.7,31.6,24.1]},"D","Цепочка делящихся чисел",[["Составь цепочку из девяти","Подходит ряд 4, 8, 1, 5, 10, 2, 6, 3, 9. В каждой соседней паре одно число делится на другое."],["Попробуй включить все десять","Число 7 может стоять лишь с краю, рядом с 1. Если 1 поставим между 7 и одним из чисел 4 или 8, то и 5, и 9 придётся поставить с краю. Ведь для них, кроме занятой 1, подходит только один сосед — 10 или 3 соответственно. Трёх краёв у ряда нет."],["Проверь числа 4 и 8","Теперь ни 4, ни 8 не могут соседствовать с 1. Второй край должен занять 5 или 9, поскольку они оба не могут оказаться рядом с 1. Значит, 4 и 8 стоят внутри и каждое должно соседствовать с другим из этой пары и с 2. Получится замкнутое кольцо 2–4–8–2, а в одном ряду без повторов это невозможно."]],""],[862,126,"В доме между любыми двумя комнатами не более одной двери, и из каждой комнаты не более одной двери ведет в сад. Всего в доме 12 дверей. Какое наименьшее число комнат может быть в этом доме?",{"0":[53.7,94.7,31.3,24.1],"1":[204.9,94.7,31.1,24.1],"2":[358.1,94.7,31.3,24.1],"3":[511.5,94.7,28.4,24.1],"4":[658,94.7,31.6,24.1]},"C","Комнаты и двери",[["Посчитай двери для четырёх комнат","При четырёх комнатах каждая из них может быть соединена с тремя другими. Считаем 4 × 3 ÷ 2 = 6 дверей между комнатами, потому что у каждой двери два конца. Ещё до четырёх дверей могут вести в сад. Всего не больше 10 дверей."],["Проверь пять комнат","Между пятью комнатами можно сделать 5 × 4 ÷ 2 = 10 дверей. Добавь две двери в сад из разных комнат, получишь 12. Наименьшее число комнат — 5."]],""],[862,152,"В таблицу 3×3 вписывают цифры так, что все 6 сумм, полученных при сложении цифр из каждой строки и каждого столбца, оказываются разными. Чему равна самая маленькая сумма всех цифр в таблице с таким свойством?",{"0":[53.7,121.7,31.3,24.1],"1":[204.9,121.7,31.1,24.1],"2":[358.1,121.7,31.3,24.1],"3":[511.5,121.7,28.4,24.1],"4":[658,121.7,31.6,24.1]},"B","Шесть разных сумм",[["Оцени общую сумму снизу","Три суммы строк вместе дают сумму всех клеток. Три суммы столбцов дают её ещё раз. Шесть разных неотрицательных сумм в сумме дают не меньше 0 + 1 + 2 + 3 + 4 + 5 = 15. Значит, сумма клеток не меньше 8."],["Заполни таблицу на сумму 8","Запиши в строках числа (0, 0, 0), (0, 0, 2) и (1, 3, 2). Суммы строк — 0, 2, 6, а столбцов — 1, 3, 4. Они все разные, а сумма всех клеток действительно 8."]],""],[862,126,"В равенстве K + A + N + G + A + R + O + O = 56 разные буквы обозначают разные цифры, а одинаковые буквы – одинаковые цифры. Наименьшее возможное значение суммы K + A + N равно",{"0":[53.7,94.6,31.3,24.1],"1":[204.9,94.6,31.1,24.1],"2":[358.2,94.6,31.3,24.1],"3":[511.5,94.6,28.4,24.1],"4":[658,94.6,31.6,24.1]},"D","Цифры в слове KANGAROO",[["Отдели искомую сумму","Из 56 выдели сумму K + A + N. Остаётся A + G + R + O + O. Здесь четыре разные цифры, причём O учитывается дважды."],["Найди предел для остатка","Наибольший остаток дают 9 на месте повторённой цифры и цифры 8, 7, 6 на остальных местах. Это 2 × 9 + 8 + 7 + 6 = 39. Искомая сумма не меньше 56 − 39 = 17."],["Проверь значение 17","Возьми K = 4, A = 8, N = 5, G = 6, R = 7, O = 9. Все цифры разные, исходная сумма равна 56, а 4 + 8 + 5 = 17."]],""],[862,189,"На рисунке изображены три одинаковых кубика. На гранях кубиков нарисованы цифры: 0, 1, 3, 4, 5, 9. Чему равна сумма чисел на нижних гранях этих кубиков?",{"0":[53.7,158.1,31.3,24.1],"1":[204.9,158.1,31.1,24.1],"2":[358.1,158.1,31.3,24.1],"3":[511.5,158.1,28.4,24.1],"4":[658,158.1,31.6,24.1]},"A","Нижние грани кубиков",[["Найди противоположную грань для 4","По первому и второму рисункам у грани 4 есть четыре соседа: 3, 1, 0 и 9. Остаётся цифра 5, она на противоположной грани."],["Найди противоположную грань для 1","По первому и третьему рисункам у грани 1 есть соседи 4, 3, 5 и 9. Значит, цифра 0 стоит напротив 1."],["Сложи нижние грани","Сверху видны 4, 0 и 5. Значит, снизу 5, 1 и 4. Их сумма равна 10."]],""]]]];
globalThis.KENGURU_LEGACY_CONDITIONS = {"2009":{"1":{"question":"Сколько треугольников на рисунке?","choices":["2","3","4","5","6"],"image":"assets/legacy-conditions/2009/task-01.webp","imageWidth":293,"imageHeight":292},"2":{"question":"200 × 9 + 200 + 9 =?","choices":["418","1909","2009","4018","20009"]},"3":{"question":"Сколько всего вершин у четырех кубиков?","choices":["32","24","16","12","4"]},"4":{"question":"Где кенгуру?","choices":["В круге и в треугольнике, но не в квадрате.","В круге и в квадрате, но не в треугольнике.","В треугольнике и в квадрате, но не в круге.","Не в треугольнике и не в квадрате, но в круге.","Не в круге и не в треугольнике, но в квадрате."],"image":"assets/legacy-conditions/2009/manual-04.webp","imageWidth":200,"imageHeight":197},"5":{"question":"В пятиэтажном доме в каждом подъезде на каждом этаже расположено по 4 квартиры. На каком этаже находится квартира с номером 71?","choices":["1","2","3","4","5"]},"6":{"question":"На клетчатой бумаге нарисовано число 930 (см. рисунок). Сколько маленьких квадратиков должно поменять цвет, чтобы получилось число 806?","choices":["5","6","7","8","9"],"image":"assets/legacy-conditions/2009/task-06.svg","imageWidth":232,"imageHeight":231},"7":{"question":"Вася подсчитал число дней в двух идущих подряд месяцах. Какое число он не мог получить?","choices":["62","60","58","59","61"]},"8":{"question":"Шоколадная плитка состоит из одинаковых долек. Маленький Владик разделил ее «по-честному»: сначала он отломал полоску из 5 долек для бабушки, а затем полоску из 7 долек для дедушки (см. рисунок). Сколько долек у него осталось?","choices":["23","28","30","35","40"],"image":"assets/legacy-conditions/2009/task-08.webp","imageWidth":198,"imageHeight":131},"9":{"question":"Произведение цифр двузначного числа не может равняться","choices":["40","36","20","13","12"]},"10":{"question":"В 3 часа ночи в замке появилось Привидение. Часы на башне замка, которые до этого показывали правильное время, пошли с обычной скоростью, но в другую сторону. Привидение исчезло с рассветом, в 4 часа 45 минут. Какое время в этот момент показывали часы?","choices":["полночь","1 ч 15 мин","1 ч 30 мин","2 ч 15 мин","7 ч 45 мин"]},"11":{"question":"В танцевальной студии занимались 25 мальчиков и 19 девочек. Каждую неделю в группу приходят два новых мальчика и три новых девочки. Через сколько недель мальчиков и девочек в этой студии станет поровну?","choices":["6","5","4","3","2"]},"12":{"question":"У скольких трехзначных чисел сумма цифр равна 2?","choices":["0","1","2","3","4"]},"13":{"question":"На картинке справа изменили цвет каждой клеточки: белый – на красный, и наоборот. Что получилось?","image":"assets/legacy-conditions/2009/task-13.webp","imageWidth":976,"imageHeight":247},"14":{"question":"В комнате сидят несколько кошек и собак. Кошачьих лап в комнате вдвое больше, чем собачьих носов. Тогда кошек в комнате","choices":["вдвое больше, чем собак","столько же, сколько собак","вдвое меньше, чем собак","в 4 раза меньше, чем собак","в 4 раза больше, чем собак"]},"15":{"question":"Город разделен улицами на квадратные кварталы. Машина выезжает из точки М и на каждом перекрестке поворачивает налево или направо. Проехав один квартал, машина повернула направо, потом три раза налево, а потом еще два раза направо. На каком из рисунков изображен маршрут машины?","image":"assets/legacy-conditions/2009/task-15.webp","imageWidth":976,"imageHeight":157},"16":{"question":"Белки Алли, Элли и Салли нашли вместе семь орехов. Каждая из них нашла хотя бы по одному ореху, и у всех оказалось разное число орехов. Алли нашла орехов меньше всех, а Элли – больше всех. Сколько орехов нашла Элли?","choices":["4","3","2","1","невозможно определить"]},"17":{"question":"Аня и Петя живут на набережной. Слева от дома Ани на набережной находится 47 домов, а справа — 23 дома. От дома Пети слева и справа по набережной находится одинаковое число домов. Сколько домов расположено между домами Ани и Пети?","choices":["10","11","12","13","14"]},"18":{"question":"Из палочек можно выкладывать цифры как на рисунке. Какова сумма цифр самого большого числа, которое удастся выложить, использовав ровно 15 палочек?","choices":["5","15","27","35","45"],"image":"assets/legacy-conditions/2009/task-18.webp","imageWidth":325,"imageHeight":189},"19":{"question":"Букет состоит из 4 цветков: красного, голубого, желтого и белого. Пчела Майя садится на каждый цветок в букете только один раз. Она начинает с красного цветка и не перелетает с желтого сразу на белый. Сколькими способами Майя может облететь все цветы?","choices":["6","4","3","2","1"]},"20":{"question":"Будем называть шестизначное число счастливым, если у него сумма цифр, стоящих на нечетных местах, равна сумме цифр, стоящих на четных местах. В каком случае можно заполнить пустые места цифрами так, чтобы получилось счастливое число?","image":"assets/legacy-conditions/2009/task-20.webp","imageWidth":913,"imageHeight":98},"21":{"question":"Какую фигуру нельзя составить из двух костяшек домино, изображенных справа?","image":"assets/legacy-conditions/2009/task-21.webp","imageWidth":951,"imageHeight":267},"22":{"question":"Дикарь Пятница написал в строчку несколько различных чисел, не превосходящих 10. Робинзон Крузо заметил, что в любой паре соседних чисел одно из них делится на другое без остатка. Какое наибольшее количество чисел мог выписать Пятница?","choices":["6","7","8","9","10"]},"23":{"question":"В доме между любыми двумя комнатами не более одной двери, и из каждой комнаты не более одной двери ведет в сад. Всего в доме 12 дверей. Какое наименьшее число комнат может быть в этом доме?","choices":["3","4","5","6","7"]},"24":{"question":"В таблицу 3×3 вписывают цифры так, что все 6 сумм, полученных при сложении цифр из каждой строки и каждого столбца, оказываются разными. Чему равна самая маленькая сумма всех цифр в таблице с таким свойством?","choices":["7","8","9","10","12"]},"25":{"question":"В равенстве K + A + N + G + A + R + O + O = 56 разные буквы обозначают разные цифры, а одинаковые буквы — одинаковые цифры. Наименьшее возможное значение суммы K + A + N равно","choices":["3","9","13","17","19"]},"26":{"question":"На рисунке изображены три одинаковых кубика. На гранях кубиков нарисованы цифры: 0, 1, 3, 4, 5, 9. Чему равна сумма чисел на нижних гранях этих кубиков?","choices":["10","9","8","7","6"],"image":"assets/legacy-conditions/2009/task-26.webp","imageWidth":409,"imageHeight":125}}};
'use strict';

(() => {
  const latin = ['A', 'B', 'C', 'D', 'E'];
  const cyrillic = ['А', 'Б', 'В', 'Г', 'Д'];
  const escape = value => String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;').replaceAll('"', '&quot;');
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const source = 'https://ipokengu.ru/public/task';
  const ink = '#173439';
  const teal = '#237e79';
  const mint = '#e5f2ea';
  const muted = '#e8eee8';
  const line = '#b3c6bf';
  const gold = '#f7dda8';

  const text = (x, y, value, size = 27, color = ink, anchor = 'middle') =>
    `<text x="${x}" y="${y}" fill="${color}" font-family="system-ui, sans-serif" font-weight="700" font-size="${size}" text-anchor="${anchor}" dominant-baseline="middle">${escape(value)}</text>`;
  const box = (x, y, w, h, fill, stroke = 'none', radius = 10) =>
    `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${radius}" fill="${fill}" stroke="${stroke}"/>`;
  const segment = (x1, y1, x2, y2, color, width = 3) =>
    `<path d="M${x1} ${y1} L${x2} ${y2}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round"/>`;
  const dot = (x, y, radius, fill) => `<circle cx="${x}" cy="${y}" r="${radius}" fill="${fill}"/>`;
  const svg = (width, height, label, inside, className = 'legacy-scene') =>
    `<svg class="${className}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escape(label)}">${inside}</svg>`;
  const image = (url, width, height) => `<image href="${url}" width="${width}" height="${height}"/>`;
  const progress = (frame, end) => Math.max(0, Math.min(1, frame / end));

  function renderOriginal(url, width, height, label, mark, frame) {
    let focus = '';
    if (mark) {
      const [x, y, w, h] = mark;
      const dash = .68 + .32 * progress(frame, 8);
      focus = `<rect x="${x - 4}" y="${y - 2}" width="${w + 8}" height="${h + 4}" rx="4" fill="none" stroke="${teal}" stroke-width="4" pathLength="1" stroke-dasharray="${dash} 1"/>`;
    }
    return svg(width, height, label, image(url, width, height) + focus);
  }

  function crop(url, width, height, [sx, sy, sw, sh], x, y, w, h) {
    return `<svg x="${x}" y="${y}" width="${w}" height="${h}" viewBox="${sx} ${sy} ${sw} ${sh}" style="overflow:hidden">${image(url, width, height)}</svg>`;
  }

  function workedScene([height, drawing], label, answer) {
    const size = 720;
    const band = answer ? 51 : 0;
    const badge = answer
      ? box(16, height, size - 32, 42, mint, line) + text(size / 2, height + 21, `Ответ ${answer}`, 24, teal)
      : '';
    return svg(size, height + band, label, drawing + badge, 'legacy-scene legacy-worked-scene');
  }

  // Extract only equations that the author explicitly uses in this step. A
  // space can group thousands, so it must not split their numeric tokens.
  const number = String.raw`[−-]?\d+(?:[ \u00a0\u202f]\d{3}(?!\d))*(?:[.,]\d+)?`;
  const operator = String.raw`[+−–×·⋅*÷:/=<>≤≥-]`;
  const equation = new RegExp(String.raw`${number}(?:\s*${operator}\s*${number})+`, 'gu');
  const tokens = new RegExp(String.raw`^(${number})|(${operator})\s*(${number})`, 'gu');

  function equationsIn(message) {
    return [...message.matchAll(equation)].map(match => match[0])
      .filter(value => /[=<>≤≥]/u.test(value))
      .map(value => [...value.matchAll(tokens)].flatMap(([, first, sign, next]) => first ? [first] : [sign, next]));
  }

  function drawEquations(rows, frame) {
    const drawing = rows.map((parts, row) => {
      const current = Math.min(parts.length - 1, Math.floor(Math.max(0, frame - row * 4) / 2));
      const sizes = parts.map((part, i) => i % 2 ? 32 : Math.max(48, 23 + part.length * 17));
      const width = sizes.reduce((sum, w) => sum + w, 0);
      const factor = Math.min(640 / width, 1);
      let x = (720 - width * factor) / 2;
      const y = 15 + row * 75;
      return box(16, y, 688, 62, '#f6f8f3') + parts.map((part, i) => {
        const w = sizes[i] * factor;
        const highlight = current === i;
        const result = i === parts.length - 1;
        const plate = (i % 2 === 0 || highlight)
          ? box(x + 2, y + 7, w - 4, 48, highlight ? gold : result ? mint : '#fff', result ? teal : 'none') : '';
        const item = plate + text(x + w / 2, y + 31, part, 32 * factor, result ? teal : ink);
        x += w;
        return item;
      }).join('');
    }).join('');
    return [rows.length * 75 + 13, drawing];
  }

  // The checked statement and the worksheet choices are transcribed together.
  // For illustrated choices, the approach below uses the original artwork.
  const authored = {
    '2001/3': {
      question: 'У Йозефа было 7 палочек. Он разломал одну из них пополам. Сколько теперь у него палочек?',
      choices: ['5', '6', '7', '8', '9'],
      draw: drawSticks,
    },
    '2002/2': {
      question: 'Чему равно число 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2?',
      choices: ['0', '2', '4', '12', '20'],
      draw: drawPairs,
    },
    '2003/3': {
      question: 'На какой картинке сердечки составляют ровно три четверти от общего числа фигурок?',
      crop: [73, 65, 662, 131],
      illustration: 'Пять рисунков с сердечками, ромбами и треугольниками, варианты от A до E',
      draw: drawHearts,
    },
    '2004/4': {
      question: 'Сережа шел по лестнице, шагая через ступеньку (первую ступеньку он пропустил). При этом он считал шаги: «Один, два, три…». После того, как он сказал «пять», оказалось, что осталась одна ступенька. Сколько всего ступенек на лестнице?',
      choices: ['5', '7', '9', '11', '12'],
      draw: drawStairs,
    },
    '2005/3': {
      question: 'Каждый из восьми кенгуру может перепрыгнуть на любую клетку квадратной таблицы 4 × 4. Им надо расположиться так, чтобы в каждой строчке и каждом столбце этой таблицы оказалось ровно по 2 кенгуру. Какое наименьшее число кенгуру должно для этого прыгнуть?',
      choices: ['4', '3', '2', '1', '0'],
      crop: [537, 8, 244, 240],
      illustration: 'Квадратная таблица с восемью кенгуру',
      draw: drawKangaroos,
    },
    '2006/10': {
      question: 'Петя прибавляет различные однозначные числа к числу 96. Сколько раз он получит трехзначное число?',
      choices: ['3', '4', '5', '6', '7'],
      draw: drawNumberLine,
    },
    '2007/1': {
      question: 'Сколько общих букв у слов КЕНГУРУ и МАТЕМАТИКА?',
      choices: ['1', '2', '3', '4', '5'],
      draw: drawLetters,
    },
    '2008/6': {
      question: 'В первом аквариуме на 12 рыбок больше, чем во втором. Сколько рыбок надо переселить из первого аквариума во второй, чтобы рыбок в них стало поровну?',
      choices: ['12', '8', '6', '4', '2'],
      draw: drawAquariums,
    },
    '2009/2': {
      question: '200 × 9 + 200 + 9 = ?',
      choices: ['418', '1909', '2009', '4018', '20009'],
    },
    '2010/2': {
      question: 'Дети измерили шагами длину дорожки. У Ани получилось 17 шагов, у Наташи 15, у Дениса 14, у Вани 13 и у Тани 12. Кто из этих детей имеет самый длинный шаг?',
      choices: ['Аня', 'Наташа', 'Денис', 'Ваня', 'Таня'],
      draw: (step, frame) => drawBars(
        ['Аня', 'Наташа', 'Денис', 'Ваня', 'Таня'], [17, 15, 14, 13, 12], step === 2 ? 4 : -1, frame),
    },
    '2011/3': {
      question: 'Через три с половиной часа отправляется поезд, на котором Сёма поедет к бабушке. Боясь проспать, он проснулся полтора часа назад. За сколько часов до отправления поезда Сёма проснулся?',
      choices: ['за полтора часа', 'за 2 часа', 'за 3 с половиной часа', 'за 4 часа', 'за 5 часов'],
      draw: (step, frame) => drawTimeline(
        ['Пробуждение', 'Сейчас', 'Отправление'], [1.5, 3.5], ['1,5 ч', '3,5 ч'], step === 2 ? '5 часов' : '', frame),
    },
    '2012/4': {
      question: 'Три воздушных шарика стоят на 12 рублей больше, чем один шарик. Сколько стоит один шарик?',
      choices: ['4 руб.', '6 руб.', '8 руб.', '10 руб.', '12 руб.'],
      draw: drawBalloons,
    },
    '2013/4': {
      question: 'Миша измерил длины пяти палочек и записал результаты этих измерений. Какой из результатов А–Д самый большой?',
      choices: ['3 дм 2 см', '3 см 7 мм', '35 мм', '3 см', '302 мм'],
      draw: (step, frame) => step === 1
        ? drawEquations(equationsIn('300 + 20 = 320'), frame)
        : drawBars(['А', 'Б', 'В', 'Г', 'Д'], [320, 37, 35, 30, 302], 0, frame, ' мм'),
    },
    '2014/1': {
      question: 'Боря выложил из одинаковых палочек слово КЕНГУРУ. Сколько букв сложены из 5 палочек?',
      choices: ['2', '3', '4', '5', '6'],
      crop: [447, 4, 348, 81],
      illustration: 'Буквы слова КЕНГУРУ, сложенные из палочек',
      draw: drawStickLetters,
    },
    '2015/2': {
      question: 'Чему равна сумма двадцати сотен и пятнадцати?',
      choices: ['35', '215', '2015', '20015', '200015'],
    },
    '2016/2': {
      question: 'Крошке Ру 17 марта исполняется 7 недель и 3 дня. Когда ему исполнится 9 недель?',
      choices: ['21 марта', '24 марта', '26 марта', '28 марта', '30 марта'],
      draw: (step, frame) => drawTimeline(
        ['17 марта', step === 2 ? '21 марта' : '8 недель', step === 2 ? '28 марта' : '9 недель'],
        [4, 7], ['4 дня', '7 дней'], step === 2 ? '11 дней' : '', frame),
    },
    '2017/1': {
      question: 'Кенга составила пять примеров на сложение. Какая сумма самая большая?',
      choices: ['2 + 0 + 1 + 7', '2 + 0 + 17', '20 + 17', '20 + 1 + 7', '201 + 7'],
      draw: drawSums,
    },
    '2018/3': {
      question: 'В Петербурге 15 марта в 16 часов пошел снег, а 16 марта в 15 часов снегопад закончился. Сколько часов он продолжался?',
      choices: ['11', '12', '23', '24', '25'],
      draw: (step, frame) => drawTimeline(
        step === 1 ? ['15 марта, 16:00', 'Полночь'] : ['15 марта, 16:00', 'Полночь', '16 марта, 15:00'],
        step === 1 ? [8] : [8, 15], step === 1 ? ['8 ч'] : ['8 ч', '15 ч'], step === 2 ? '23 часа' : '', frame, 23),
    },
    '2019/1': {
      question: 'В зоопарке 21 ноября 2018 года родился кенгуренок. Сколько месяцев ему исполнилось 21 марта 2019 года?',
      choices: ['3', '4', '5', '6', '7'],
      draw: (step, frame) => drawTimeline(
        step === 1 ? ['21 нояб.', '21 дек.', '21 янв.'] : ['21 нояб.', '21 дек.', '21 янв.', '21 февр.', '21 марта'],
        step === 1 ? [1, 1] : [1, 1, 1, 1], step === 1 ? ['1 мес.', '1 мес.'] : ['1 мес.', '1 мес.', '1 мес.', '1 мес.'],
        step === 2 ? '4 месяца' : '', frame, 4),
    },
  };

  function drawSticks(step, frame) {
    let drawing = '';
    for (let i = 0; i < 6; i++) drawing += segment(101 + i * 70, 38, 101 + i * 70, 117, teal, 11);
    drawing += text(275, 150, '6 целых', 26);
    const gap = step === 1 ? 0 : 20 + 9 * progress(frame, 8);
    drawing += segment(567 - gap, 38, 567 - gap, 74, '#bc6340', 11);
    drawing += segment(567 + gap, 82, 567 + gap, 117, '#bc6340', 11);
    drawing += text(567, 150, step === 1 ? 'сломанная' : '2 половины', 26);
    return [180, drawing];
  }

  function drawPairs(step, frame) {
    let drawing = box(17, 22, 119, 61, mint) + text(77, 52, '2 + 2', 30);
    const active = Math.min(3, Math.floor(Math.max(0, frame) / 4));
    for (let i = 0; i < 4; i++) {
      const x = 151 + 139 * i;
      drawing += box(x, 22, 130, 61, step === 1 && i === active ? gold : muted);
      drawing += text(x + 65, 52, step === 1 ? '−2 + 2' : '0', 30);
      if (step === 1) drawing += segment(x + 65, 89, x + 65, 111, teal) + text(x + 65, 137, '0', 26, teal);
    }
    if (step === 2) drawing += text(360, 137, '2 + 2 = 4', 33, teal);
    return [173, drawing];
  }

  function drawHearts(step, frame, card) {
    if (step === 1) {
      let drawing = '';
      for (let i = 0; i < 4; i++) {
        const x = 105 + i * 128;
        drawing += box(x, 40, 105, 81, i === 3 ? muted : mint, line);
        drawing += text(x + 52, 80, i === 3 ? '◇' : '♥', 49, i === 3 ? ink : '#a34849');
      }
      return [175, drawing + text(360, 145, '3 из 4', 30, teal)];
    }
    const [url, w, h] = card;
    const choiceImage = globalThis.KENGURU_CHOICE_LAYOUTS?.['2003-3-4/3']?.options[3]?.image;
    const drawing = choiceImage
      ? `<image href="${escape(choiceImage)}" x="251" y="11" width="228" height="240"/>`
      : crop(url, w, h, [493, 66, 76, 80], 251, 11, 228, 240);
    const alpha = .45 + progress(frame, 9) * .55;
    return [260, drawing +
      `<g opacity="${alpha}">` +
      box(256, 15, 216, 158, 'none', '#a34849') + box(256, 176, 216, 73, 'none', teal) +
      text(490, 94, '9 сердец', 27, '#a34849', 'start') +
      text(490, 206, '3 другие фигуры', 23, teal, 'start') + '</g>'];
  }

  function drawStairs(step, frame) {
    let drawing = '';
    for (let i = 1; i <= 11; i++) {
      const x = 26 + 60 * (i - 1);
      const y = 176 - 13 * (i - 1);
      const landed = i % 2 === 0;
      const active = landed && i / 2 === Math.min(5, 1 + Math.floor(Math.max(frame, 0) / 4));
      const remaining = i === 11 && step === 2;
      drawing += box(x, y, 59, 36, active ? gold : remaining || landed ? mint : muted, line, 4);
      if (i < 11 || remaining) drawing += text(x + 30, y + 18, i, 24, landed || remaining ? teal : ink);
      if (landed) drawing += dot(x + 30, y - 15, active ? 8 : 5, teal);
      if (remaining) drawing += text(x + 30, y - 20, '+1', 22, teal);
    }
    return [225, drawing];
  }

  function drawKangaroos(step, frame, card) {
    const [url, w, h] = card;
    const locations = [[0, 0], [0, 1], [1, 0], [1, 3], [2, 2], [2, 3], [3, 2], [1, 2]];
    let drawing = '';
    for (let row = 0; row < 4; row++) {
      for (let col = 0; col < 4; col++) {
        const fill = step === 1 && (row === 1 || col === 2) ? gold
          : row === 3 && col === 1 ? mint : '#fff';
        drawing += box(204 + col * 64, 14 + row * 64, 64, 64, fill, line, 0);
      }
    }
    const moving = step === 2 ? (frame === 0 ? 1 : progress(frame, 10)) : 0;
    if (step === 2 && frame > 0) {
      drawing += `<path d="M364 110 Q230 144 300 238" fill="none" stroke="${teal}" stroke-width="3" stroke-dasharray="7 5"/>`;
    }
    locations.forEach(([row, col], i) => {
      const active = i === locations.length - 1;
      const shift = active ? moving : 0;
      const x = 210 + col * 64 - shift * 64;
      const y = 21 + row * 64 + shift * 128 - 37 * Math.sin(shift * Math.PI);
      if (active) drawing += box(x - 3, y - 3, 58, 57, mint, teal, 7);
      drawing += `<svg x="${x}" y="${y}" width="52" height="50" viewBox="549 19 49 46" style="overflow:hidden;mix-blend-mode:multiply">${image(url, w, h)}</svg>`;
    });
    const counts = moving === 1 ? [2, 2, 2, 2] : moving === 0 ? [2, 3, 2, 1] : [2, 2, 2, 1];
    for (let i = 0; i < 4; i++) {
      drawing += text(489, 46 + i * 64, counts[i], 24, teal);
      drawing += text(236 + i * 64, 296, i === 1 ? counts[3] : i === 2 ? counts[1] : 2, 24, teal);
    }
    return [321, drawing];
  }

  function drawNumberLine(step, frame) {
    let drawing = segment(44, 99, 676, 99, line, 4);
    for (let i = 0; i < 10; i++) {
      const x = 45 + i * 70;
      const marked = i === 4 || (step === 2 && i > 4);
      const active = i === 4 + Math.min(step === 1 ? 0 : 5, Math.floor(Math.max(0, frame) / 3));
      if (marked) drawing += box(x - 28, 53, 56, 44, active ? gold : mint);
      drawing += text(x, 75, 96 + i, 23, marked ? teal : ink) + dot(x, 99, marked ? 6 : 4, marked ? teal : line);
      if (marked) drawing += text(x, 126, '+' + i, 20, teal);
    }
    return [155, drawing];
  }

  function drawLetters(step, frame) {
    const words = ['КЕНГУРУ', 'МАТЕМАТИКА'];
    const active = Math.min(words[0].length - 1, Math.floor(Math.max(0, frame) / 3));
    return [166, words.map((word, row) => [...word].map((letter, i) => {
      const x = 360 - word.length * 32 + i * 64;
      const y = 19 + row * 67;
      const common = step === 2 && 'КЕ'.includes(letter);
      const comparable = step === 1 && (row === 0 ? i === active : letter === words[0][active]);
      return box(x, y, 56, 54, common ? mint : comparable ? gold : muted, common ? teal : line) +
        text(x + 28, y + 27, letter, 30, common ? teal : ink);
    }).join('')).join('')];
  }

  function drawAquariums(step, frame) {
    const moved = step === 1 ? 1 : 6;
    const now = frame === 0 ? moved : Math.min(moved, 1 + Math.floor(frame / 3));
    let drawing = '';
    for (let tank = 0; tank < 2; tank++) {
      const x = 21 + tank * 365;
      drawing += box(x, 18, 313, 128, mint, line);
      drawing += text(x + 156, 40, tank ? 'Второй аквариум' : 'Первый аквариум', 22);
      drawing += text(x + 40, 96, '□ +', 25, teal);
      for (let i = 0; i < (tank ? now : 12 - now); i++) {
        drawing += dot(x + 81 + (i % 6) * 36, 81 + Math.floor(i / 6) * 33, 11, tank ? '#bc6340' : teal);
      }
    }
    drawing += text(360, 82, '→', 27, ink);
    const difference = now === 6 ? '6 = 6' : `${12 - now} − ${now} = ${12 - 2 * now}`;
    drawing += text(360, 174, difference, 29, teal);
    return [197, drawing];
  }

  function drawBars(names, values, highlighted, frame, unit = '') {
    const max = Math.max(...values);
    const active = Math.min(values.length - 1, Math.floor(Math.max(0, frame) / 3));
    let drawing = '';
    for (let i = 0; i < values.length; i++) {
      const y = 12 + i * 46;
      const w = values[i] / max * 450;
      drawing += text(124, y + 17, names[i], 22, ink, 'end');
      drawing += box(146, y, w, 34, i === highlighted ? teal : i === active ? gold : muted, line, 7);
      drawing += text(156 + w, y + 17, values[i] + unit, 22, i === highlighted ? teal : ink, 'start');
    }
    return [values.length * 46 + 6, drawing];
  }

  function drawTimeline(labels, sizes, durations, total, frame, span = sizes.reduce((sum, size) => sum + size, 0)) {
    const active = Math.min(sizes.length - 1, Math.floor(Math.max(0, frame) / 6));
    let x = 103;
    let drawing = '';
    sizes.forEach((size, i) => {
      const end = x + 514 * size / span;
      drawing += segment(x, 65, end, 65, i === active ? '#c07848' : teal, 8);
      drawing += dot(x, 65, 8, teal);
      drawing += text(x, 100, labels[i], 21);
      drawing += text((x + end) / 2, 34, durations[i], 25, teal);
      x = end;
    });
    drawing += dot(x, 65, 8, teal) + text(x, 100, labels.at(-1), 21);
    if (total) drawing += box(103, 129, 514, 40, mint) + text(360, 149, total, 26, teal);
    return [total ? 183 : 128, drawing];
  }

  function drawBalloons(step, frame) {
    const active = Math.min(2, 1 + Math.floor(Math.max(0, frame) / 4));
    let drawing = segment(343, 62, 586, 62, teal, 3) + text(464, 36, '12 руб.', 26, teal);
    for (let i = 0; i < 3; i++) {
      const x = 175 + i * 144;
      const color = i === 0 ? '#a9b9b2' : i === active ? '#bc6340' : teal;
      drawing += dot(x, 118, 38, color);
      drawing += box(x - 6, 151, 12, 12, color, 'none', 0);
      drawing += segment(x, 162, x, 181, color);
      drawing += text(x, 207, i === 0 ? 'вычитаем' : step === 1 ? '?' : '6 руб.', 25, color);
      if (i === 0) drawing += segment(x - 45, 165, x + 45, 77, '#7d4940', 4);
    }
    return [239, drawing];
  }

  function drawStickLetters(step, frame, card) {
    const [url, w, h] = card;
    const sources = [[449, 42], [492, 48], [541, 53], [597, 49], [645, 46], [692, 52], [745, 48]];
    const values = [4, 5, 5, 3, 3, 5, 3];
    const active = Math.min(6, Math.floor(Math.max(0, frame) / 3));
    let drawing = '';
    for (let i = 0; i < sources.length; i++) {
      const [sx, sw] = sources[i];
      const x = 24 + i * 98;
      const relevant = step === 2 ? values[i] === 5 : values[i] !== 5;
      drawing += box(x, 21, 85, 126, relevant ? mint : muted, relevant ? teal : line);
      drawing += crop(url, w, h, [sx, 8, sw, 75], x + 14, 30, 56, 77);
      if (relevant) drawing += text(x + 43, 125, values[i], 24, active === i ? '#a24d36' : teal);
    }
    return [167, drawing];
  }

  function drawSums(step, frame) {
    if (step === 2) return drawBars(['А', 'Б', 'В', 'Г', 'Д'], [10, 19, 37, 28, 208], 4, frame);
    const expressions = authored['2017/1'].choices;
    const drawing = expressions.map((value, i) => {
      const x = 12 + i * 140;
      return box(x, 25, 135, 61, i === 4 ? mint : muted, i === 4 ? teal : line) +
        text(x + 67, 55, value, 22, i === 4 ? teal : ink);
    }).join('');
    return [113, drawing];
  }

  for (const [year, label, tasks] of globalThis.KENGURU_LEGACY ?? []) {
    const letters = year < 2008 ? latin : cyrillic;
    const lessons = [];
    const scenes = [];
    for (const [i, [width, height, , marks, key, name, explanation, note]] of tasks.entries()) {
      const number = i + 1;
      const answer = key === '?' ? null : latin.indexOf(key);
      const originalImage = `assets/years/${year}/task-${String(number).padStart(2, '0')}.webp`;
      const card = [originalImage, width, height];
      const authoredTask = authored[year + '/' + number];
      const imported = globalThis.KENGURU_LEGACY_CONDITIONS?.[year]?.[number];
      const native = authoredTask ?? imported;
      const illustration = !authoredTask && imported?.image
        ? svg(imported.imageWidth, imported.imageHeight, 'Рисунки и варианты из условия',
            `<image href="${escape(imported.image)}" width="${imported.imageWidth}" height="${imported.imageHeight}"/>`)
          .replace('<svg ', `<svg style="max-width:${imported.imageWidth}px" `)
        : '';
      const steps = [
        ['Твоё решение', 'Условие задачи', 'Выбери свой вариант ответа.'],
        ...explanation.map(([heading, message], stage) => [
          stage === explanation.length - 1 ? 'Ответ' : 'Шаг ' + (stage + 1), heading, message,
        ]),
      ];
      const formulas = explanation.map(([, message]) => equationsIn(message));
      const choice = answer === null ? '' : letters[answer];
      const description = `Условие и варианты задачи ${number} из оригинала.`;
      lessons.push({
        number,
        title: name,
        short: name,
        skill: '',
        answer,
        choices: native?.choices ?? ['', '', '', '', ''],
        choiceImages: native?.choiceImages,
        question: native?.question ?? '',
        conditionImage: !authoredTask ? imported?.image : undefined,
        questionNote: note,
        legacyOriginal: true,
        hideIntroText: Boolean(native),
        showCompletedStep: true,
        points: i < 10 ? 3 : i < 20 ? 4 : 5,
        originalImage,
        steps,
      });
      scenes.push((step, frame) => {
        if (step === 0 && authoredTask) {
          if (!authoredTask.crop) return '';
          const region = authoredTask.crop;
          const cropHeight = Math.round(720 * region[3] / Math.max(600, region[2]));
          const cropWidth = cropHeight * region[2] / region[3];
          return svg(720, cropHeight, authoredTask.illustration,
            crop(...card, region, (720 - cropWidth) / 2, 0, cropWidth, cropHeight));
        }
        if (step === 0 && native) return illustration;
        const final = step === steps.length - 1;
        const revealed = final ? choice : '';
        const answerLabel = revealed ? ` Ответ ${revealed}.` : '';
        if (step > 0) {
          const content = authoredTask?.draw
            ? authoredTask.draw(step, frame * 3, card)
            : formulas[step - 1].length ? drawEquations(formulas[step - 1], frame * 5) : null;
          if (content) return workedScene(content, steps[step][1] + '. ' + steps[step][2] + answerLabel, revealed);
          if (native) {
            if (!revealed) return '';
            return workedScene([0, ''], description + answerLabel, revealed);
          }
        }
        return renderOriginal(...card, description + answerLabel, final ? marks[answer] : null, frame);
      });
    }

    archive[year] = {
      year,
      id: year + '-3-4',
      grades: [3, 4],
      label,
      answerLetters: letters,
      sources: {
        tasksUrl: `${source}/kenguru_${year}_class_3-4.pdf`,
        answersUrl: `${source}/kenguru_${year}_answers.pdf`,
        solutionUrl: null,
      },
      lessons,
      scenes,
    };
  }
})();

